181:   io.defer := defer
182: 
183:   // ========== FORMAL ASSERTIONS ==========
184: 
185:   // -----------------------------------------------------------------------
186:   // 1. Mutual Exclusion (Safety): At most one process in critical section
187:   //    The critical section is at Loc.L9. The bakery algorithm guarantees
188:   //    mutual exclusion, which is the fundamental safety property.
189:   // -----------------------------------------------------------------------
190:   val in_cs = Wire(UInt((HIPROC + 1).W))
191:   in_cs := Cat(
192:     pc(2) === Loc.L9,
193:     pc(1) === Loc.L9,
194:     pc(0) === Loc.L9
195:   )
196:   assertOneHot0(in_cs, "MutualExclusion_at_most_one_process_in_CS")
197: 
198:   // -----------------------------------------------------------------------
199:   // 2. Ticket Consistency: A process in the critical section must have
200:   //    its ticket flag set (ticket is set at L2, cleared at L10).
201:   // -----------------------------------------------------------------------
202:   for (i <- 0 to HIPROC) {
203:     val sUInt = i.U
204:     fvAssert(
205:       !(pc(sUInt) === Loc.L9) || ticket(sUInt),
206:       s"TicketSet_InCS_${i}"
207:     )
208:   }
209: 
210:   // -----------------------------------------------------------------------
211:   // 3. Choosing Consistency: choosing flag must be true only during the
212:   //    ticket-acquisition phase (L2-L3). At L2 choosing is set, at L3 it
213:   //    is cleared. It must be false in the critical section and idle state.
214:   // -----------------------------------------------------------------------
215:   for (i <- 0 to HIPROC) {
216:     val sUInt = i.U
217:     fvAssert(
218:       !choosing(sUInt) || (pc(sUInt) === Loc.L2) || (pc(sUInt) === Loc.L3),
219:       s"ChoosingOnlyInL2L3_${i}"
220:     )
221:   }
222: 
223:   // -----------------------------------------------------------------------
224:   // 4. Bounded Liveness / Progress: When a process is selected and in the
225:   //    trying region (L4-L8), it must reach the critical section (L9) within
226:   //    a bounded number of cycles during which it is selected.
227:   //
228:   //    The trying region consists of:
229:   //      L4: initialize j=0
230:   //      L5: check if j <= HIPROC
231:   //      L6: wait until process j is not choosing
232:   //      L7: wait until priority condition passes
233:   //      L8: increment j
234:   //
235:   //    With 3 processes (HIPROC=2), the worst case is 3 iterations of the
236:   //    L5→L6→L7→L8 loop, taking at most ~4 cycles per iteration = 12 cycles,
237:   //    plus L4→L5 and the final L5→L9. Bound of 30 is generous.
238:   // -----------------------------------------------------------------------
239:   for (i <- 0 to HIPROC) {
240:     val sUInt = i.U
241:     val trying = (pc(sUInt) === Loc.L4) ||
242:                  (pc(sUInt) === Loc.L5) ||
243:                  (pc(sUInt) === Loc.L6) ||
244:                  (pc(sUInt) === Loc.L7) ||
245:                  (pc(sUInt) === Loc.L8)
246:     val selected_and_trying = (selReg === sUInt) && trying
247:     val in_critical = pc(sUInt) === Loc.L9
248:     assertLivenessTimer(
249:       selected_and_trying,
250:       in_critical,
251:       30,
252:       s"BoundedLiveness_Process_${i}_reaches_CS_within_30_selected_cycles"
253:     )
254:   }
255: 
256: }
257: 
258: object VerilogGenerator extends App {
259:   emitVerilog(new bakery(), args)
260: }
